out = {}
for name, pairs in PAIRS.items():
    t = (M / name).read_text(encoding="utf-8")
    for old, new in pairs:
        if t.count(old) != 1:
            sys.exit(f"Could not find the expected text in map/{name} ({old.strip()[:70]!r}). Nothing was written.")
        t = t.replace(old, new)
    out[name] = t
for name, t in out.items():
    (M / name).write_text(t, encoding="utf-8")
print("Done: Climate TRACE columns, the view row, OpenStreetMap on the outlines.")
